#!/usr/bin/env bash
# herdr の Claude Code 用フックを呼ぶ hooks のエントリを、herdr の公式インストーラが生成した
# settings.json と、リポジトリの .config/claude/settings.json とで比べる (Issue #755)。
# スクリプト本体はビルド時に生成されて herdr に追従するが、エントリは手書きなので、herdr を
# 上げて matcher などが変わると、フックが呼ばれないまま pane が普通のシェルで戻る。
# flake.nix の checks.herdr-claude-hook-entries がこのスクリプトを呼ぶ。
# Compare the hooks entries that call herdr's Claude Code hook between the settings.json
# generated by herdr's official installer and the repo's .config/claude/settings.json
# (Issue #755). The script itself is generated at build time and follows herdr, but the
# entry is hand-written; if a herdr bump changes the matcher or similar, the hook stops
# firing and panes silently come back as plain shells.
# Called from checks.herdr-claude-hook-entries in flake.nix.
#
# usage: herdr_claude_hook_entries.sh <generated settings.json> <repo settings.json>
set -euo pipefail

if [[ $# -ne 2 ]]; then
  echo "usage: $0 <generated settings.json> <repo settings.json>" >&2
  exit 2
fi
generated=$1
repo=$2

# herdr のフックを呼ぶエントリを、イベント名・matcher・スクリプトの後ろの引数・timeout に
# 正規化して並べる。スクリプトのパスは生成物 (Nix store、引用符つき) とリポジトリ ($HOME) で
# 違うので比べない。
# Normalize every entry that calls herdr's hook into event, matcher, the arguments after the
# script, and timeout. The script path differs between the generated file (a quoted Nix store
# path) and the repo ($HOME), so it is left out of the comparison.
herdr_entries=$(
  cat <<'JQ'
[ (.hooks // {}) | to_entries[] | .key as $event | .value[]
  | (.matcher // "") as $matcher
  | .hooks[]
  | select(.type == "command" and (.command | test("hooks/herdr-agent-state\\.sh")))
  | { event: $event,
      matcher: $matcher,
      args: (.command | capture("hooks/herdr-agent-state\\.sh['\"]?(?<args>.*)$").args
             | sub("^\\s+"; "")),
      timeout: .timeout } ]
| sort
JQ
)

want=$(jq -S "$herdr_entries" "$generated")
have=$(jq -S "$herdr_entries" "$repo")

# 生成物にエントリが無いなら、herdr がスクリプトの名前か settings.json の書き方を変えている
# No entry in the generated file means herdr renamed the script or changed how it writes settings.json
if [[ $(jq '[.[] | select(.event == "SessionStart")] | length' <<<"$want") -eq 0 ]]; then
  echo "error: herdr のインストーラが生成した settings.json に、SessionStart の herdr のエントリが無い" >&2
  echo "error: the settings.json generated by herdr's installer has no SessionStart entry for herdr's hook" >&2
  echo "  generated: $generated" >&2
  exit 1
fi

# herdr の integration status はスクリプトの存在と版しか見ないので、エントリが無くても current と表示する
# herdr's integration status only looks at the script and its version, so it shows current even without the entry
if [[ $(jq '[.[] | select(.event == "SessionStart")] | length' <<<"$have") -eq 0 ]]; then
  echo "error: リポジトリの settings.json の SessionStart に、hooks/herdr-agent-state.sh を呼ぶエントリが無い" >&2
  echo "error: the repo settings.json has no SessionStart entry that calls hooks/herdr-agent-state.sh" >&2
  echo "  repo: $repo" >&2
  echo "  .config/claude/settings.json に生成物 (generated) のエントリを足す / Add the generated entry to .config/claude/settings.json" >&2
  exit 1
fi

if [[ "$want" != "$have" ]]; then
  echo "error: herdr のフックのエントリが、herdr のインストーラが生成したものとずれている" >&2
  echo "error: the entries for herdr's hook drift from the ones herdr's installer generates" >&2
  echo "  .config/claude/settings.json を生成物 (generated) に合わせて直す / Update .config/claude/settings.json to match the generated entries" >&2
  diff -u --label generated --label repo <(printf '%s\n' "$want") <(printf '%s\n' "$have") >&2 || true
  exit 1
fi

echo "ok: herdr のフックのエントリは生成物と一致している / herdr hook entries match the generated settings.json"
